### FUNCION: populateRowLabels
```js
function populateRowLabels() {
    const rowLabelsContainer = document.getElementById('row-labels');
    if (!rowLabelsContainer) return;

    for (let r = 1; r <= NUM_ROWS; r++) {
        const label = document.createElement('div');
        label.className = 'label row-number';
        label.dataset.row = r;
        label.textContent = r;
        rowLabelsContainer.appendChild(label);
    }
}
```

