### FUNCION: initializeGrid
```javascript
function initializeGrid() {
    const container = document.getElementById('spreadsheet-container');
    // Clear all existing row wrappers, but keep the column labels structure intact.
    // We iterate over children and remove those that look like row content (i.e., not the corner or column headers).
    Array.from(container.children).forEach(child => {
        if (!child.classList.contains('col-header') && !child.classList.contains('corner-cell')) {
            child.remove();
        }
    });

    for (let r = 1; r <= NUM_ROWS; r++) {
        // Create a wrapper that spans both row label and cell grid area for structural integrity
        const rowWrapper = document.createElement('div');
        rowWrapper.className = 'spreadsheet-row';
        rowWrapper.dataset.row = r;

        // 1. Row Label Column (The number)
        const rowLabel = document.createElement('div');
        rowLabel.className = 'row-label';
        rowLabel.textContent = r;
        rowLabel.dataset.row = r; // Store data for identification

        // 2. Cell Grid Container (A1 to J1)
        const cellGridContainer = document.createElement('div');
        cellGridContainer.className = 'cell-grid';

        for (let c = 0; c < NUM_COLUMNS; c++) {
            const coord = getCoord(c, r);
            const cell = document.createElement('div');
            cell.className = 'spreadsheet-cell';
            cell.dataset.coord = coord;
            cell.setAttribute('tabindex', 0); // Make cells focusable

            // Attach click listener for selection and editing (R1, R10)
            cell.addEventListener('click', handleCellClick);

            // Attach input/focus listener for direct typing (R1)
            cell.addEventListener('input', handleCellInput);
            cell.addEventListener('focus', () => {
                activeCellElement = cell;
                document.getElementById('btn-clear-selection').disabled = false;
            });

            cellGridContainer.appendChild(cell);
        }

        // Append label and grid container to the row wrapper
        rowWrapper.appendChild(rowLabel);
        rowWrapper.appendChild(cellGridContainer);

        // Append the complete row structure to the main container
        container.appendChild(rowWrapper); 
    }
}
