function initializeGrid() {
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    // Clear existing dynamic content (rows) from the container
    // We keep column labels intact, so we clear everything except #column-labels if possible, 
    // but clearing all children is safer for a full re-initialization.
    const children = spreadsheetContainer.children;
    for(let i=0; i<children.length; i++) {
        if (children[i].id !== 'column-labels') {
            children[i].remove();
        }
    }

    for (let r = 1; r <= NUM_ROWS; r++) {
        // 1. Create Row Label Element (The number 'r')
        const rowLabel = document.createElement('div');
        rowLabel.className = 'row-label'; // Use the defined class for styling/structure
        rowLabel.dataset.row = r;
        rowLabel.textContent = r;

        // 2. Create the container for cells in this row (The content that goes into the main grid area)
